const input = $input.first();
const body = input.json.body || input.json || {};
const binary = input.binary || {};

let textContent = body.rawText || '';
let userId = body.userId || null;
let userRole = (body.userRole || '').toUpperCase().trim();
let userGender = (body.userGender || '').toLowerCase().trim(); // 'male', 'female', or ''
let title = body.title || 'Untitled';
let scriptType = body.scriptType || 'tv_audition';

// Keep accentHint as empty string if not specified (for auto-detect)
// Only normalize to lowercase, don't default to australian
let accentHint = (body.accentHint || '').toLowerCase().trim();

let inputType = 'raw_text';
let fileName = '';
if (binary && Object.keys(binary).length > 0) {
  const fileKey = Object.keys(binary)[0];
  const file = binary[fileKey];
  const mimeType = file.mimeType || '';
  fileName = file.fileName || '';
  if (!title || title === 'Untitled') {
    title = fileName.replace(/\.[^.]+$/, '').replace(/[_-]/g, ' ').trim();
  }
  if (mimeType === 'application/pdf' || fileName.toLowerCase().endsWith('.pdf')) {
    inputType = 'pdf';
  }
}

return [{ json: { inputType, textContent, userId, userRole, userGender, title, fileName, scriptType, accentHint }, binary }];

const input = $input.first();
const detect = $('Extract Input').first().json;

let text = '';
if (input.json.text) text = input.json.text;
else if (input.json.data) text = input.json.data;
else text = JSON.stringify(input.json);

text = String(text || '')
  // Normalize all line breaks to \n first
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n')
  .replace(/\\n/g, '\n')

  // FIX SCENE NUMBER CONCATENATION - handles "NIGHT2 2" â†’ "NIGHT\n2"
  .replace(/(\b(?:DAY|NIGHT|MORNING|EVENING|AFTERNOON|DAWN|DUSK|LATER|CONTINUOUS|SAME))\s*(\d+)\s+\2\b/gi, '$1\n$2')

  // Fix scene numbers stuck to words like "house2" â†’ "house\n2" 
  .replace(/([a-zA-Z])(\d+)\s+\2\b/g, '$1\n$2')

  // Remove script artifacts
  .replace(/^\s*(CONTINUED|\(CONTINUED\)|\(MORE\))\s*$/gim, '')
  .replace(/^\s*\d+\.?\s*$/gm, '')

  // Fix smart quotes and dashes
  .replace(/[\u2018\u2019]/g, "'")
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/\u2014/g, ' - ')
  .replace(/\u2026/g, '...')

  // JOIN DIALOGUE LINES: Replace single newlines with space (keeps paragraph breaks)
  .replace(/([a-zA-Z,;:!?'"])\n([a-zA-Z])/g, '$1 $2')

  // Clean up whitespace
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{ json: { ...detect, textContent: text, textLength: text.length } }];

const input = $input.first().json;
let text = (input.textContent || '')
  .replace(/[\u2018\u2019]/g, "'")
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{4,}/g, '\n\n\n')
  .trim();
return [{ json: { ...input, textContent: text, textLength: text.length } }];

// Parse Gemini Structure response
const input = $input.first().json;
const detect = $('Extract Input').first().json;

let parsed = null;
try {
  let content = input.choices?.[0]?.message?.content || '{}';
  content = content
    .replace(/```json\s*/gi, '')
    .replace(/```/g, '')
    .replace(/[\x00-\x1F\x7F]/g, ' ')
    .trim();

  const jsonStart = content.indexOf('{');
  const jsonEnd = content.lastIndexOf('}');
  if (jsonStart !== -1 && jsonEnd !== -1) {
    content = content.substring(jsonStart, jsonEnd + 1);
  }

  parsed = JSON.parse(content);

  // Handle array response from Gemini
  if (Array.isArray(parsed)) {
    parsed = parsed[0];
  }
} catch (e) {
  throw new Error('Failed to parse structure: ' + e.message);
}

// Build lines for emotion pass (include parentheticals from content for emotion hints)
const linesForEmotion = (parsed.lines || []).map((l, i) => ({
  idx: i,
  char: l.character || 'NARRATOR',
  text: l.content || '',
  type: l.type || 'dialogue'
}));

// Pass characters to emotions node for trait analysis
const charactersForTraits = (parsed.characters || []).map(c => ({
  name: c.name || '',
  gender: c.gender || 'unknown',
  is_user_character: c.is_user_character || false
}));

return [{ json: { 
  ...detect, 
  structure: parsed,
  linesForEmotion: linesForEmotion,
  characters: charactersForTraits
} }];

