const input = $input.first().json;
const prevData = $('Parse Structure').first().json;
const detect = $('Extract Input').first().json;

// Parse emotions response (now includes character traits AND segments)
let emotionsData = { emotions: [], characters: [], segments: {} };
try {
  let content = input.choices?.[0]?.message?.content || '{}';
  content = content.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(content);

  // Handle both old format (array) and new format (object)
  if (Array.isArray(parsed)) {
    emotionsData = { emotions: parsed, characters: [], segments: {} };
  } else {
    emotionsData = {
      emotions: parsed.emotions || [],
      characters: parsed.characters || [],
      segments: parsed.segments || {}
    };
  }
} catch (e) {
  emotionsData = { emotions: [], characters: [], segments: {} };
}

const structure = prevData.structure;
const lines = structure.lines || [];
const emotions = emotionsData.emotions;
const characterTraits = emotionsData.characters;
const segments = emotionsData.segments;

// Merge emotions AND segments into lines
lines.forEach((line, i) => {
  line.emotion = emotions[i] || 'neutral';
  // Add practice_segments if this line has them (user character lines only)
  const lineSegments = segments[String(i)] || segments[i];
  if (lineSegments && Array.isArray(lineSegments)) {
    line.practice_segments = lineSegments;
  }
});

// ============================================================================
// ACCENT DETECTION
// ============================================================================
const ACCENT_MAP = {
  'australian': 'en-AU', 
  'british': 'en-GB', 
  'american': 'en-US', 
  'indian': 'en-IN'
};

let finalAccent = detect.accentHint;
if (!finalAccent || finalAccent === '' || finalAccent === 'auto-detect') {
  finalAccent = (structure.detected_accent || 'american').toLowerCase();
}
if (!ACCENT_MAP[finalAccent]) {
  finalAccent = 'american';
}
const locale = ACCENT_MAP[finalAccent];

// ============================================================================
// VOICE MAPPING BY TRAITS
// ============================================================================
const VOICE_PROFILES = {
  female: {
    Kore:         { ages: ['teen', 'young_adult'], archetypes: ['protagonist', 'friend'], qualities: ['energetic', 'bright', 'warm'] },
    Despina:      { ages: ['teen', 'young_adult'], archetypes: ['comic_relief', 'friend'], qualities: ['energetic', 'bright'] },
    Zephyr:       { ages: ['young_adult', 'adult'], archetypes: ['friend', 'love_interest'], qualities: ['soft', 'warm', 'calm'] },
    Aoede:        { ages: ['young_adult', 'adult'], archetypes: ['protagonist', 'love_interest'], qualities: ['warm', 'bright'] },
    Sulafat:      { ages: ['adult'], archetypes: ['friend', 'supporting'], qualities: ['warm', 'calm'] },
    Achernar:     { ages: ['adult'], archetypes: ['love_interest', 'friend'], qualities: ['soft', 'warm'] },
    Erinome:      { ages: ['young_adult', 'adult'], archetypes: ['love_interest', 'supporting'], qualities: ['soft', 'warm'] },
    Leda:         { ages: ['adult', 'mature'], archetypes: ['authority', 'mentor', 'narrator'], qualities: ['calm', 'commanding'] },
    Autonoe:      { ages: ['mature', 'adult'], archetypes: ['mentor', 'authority'], qualities: ['calm', 'warm', 'soft'] },
    Gacrux:       { ages: ['adult', 'mature'], archetypes: ['authority', 'antagonist'], qualities: ['commanding', 'sharp'] },
    Vindemiatrix: { ages: ['adult', 'mature'], archetypes: ['antagonist', 'authority'], qualities: ['sharp', 'commanding'] },
    Callirrhoe:   { ages: ['adult'], archetypes: ['antagonist', 'supporting'], qualities: ['sharp', 'gravelly'] },
  },
  male: {
    Puck:         { ages: ['teen', 'young_adult'], archetypes: ['comic_relief', 'friend'], qualities: ['energetic', 'bright'] },
    Achird:       { ages: ['young_adult', 'adult'], archetypes: ['protagonist', 'friend', 'supporting'], qualities: ['warm', 'calm'] },
    Orus:         { ages: ['adult', 'young_adult'], archetypes: ['protagonist', 'authority'], qualities: ['commanding', 'warm'] },
    Sadachbia:    { ages: ['adult'], archetypes: ['friend', 'supporting'], qualities: ['warm', 'calm'] },
    Iapetus:      { ages: ['young_adult', 'adult'], archetypes: ['love_interest', 'friend'], qualities: ['warm', 'soft'] },
    Algieba:      { ages: ['adult', 'young_adult'], archetypes: ['comic_relief', 'friend'], qualities: ['energetic', 'warm'] },
    Enceladus:    { ages: ['adult', 'mature'], archetypes: ['mentor', 'authority'], qualities: ['calm', 'soft', 'warm'] },
    Schedar:      { ages: ['mature', 'adult'], archetypes: ['authority', 'mentor'], qualities: ['commanding', 'gravelly'] },
    Alnilam:      { ages: ['mature', 'adult'], archetypes: ['authority', 'mentor'], qualities: ['commanding', 'calm'] },
    Rasalgethi:   { ages: ['mature', 'adult'], archetypes: ['narrator', 'mentor'], qualities: ['calm', 'warm'] },
    Fenrir:       { ages: ['adult', 'mature'], archetypes: ['antagonist', 'authority'], qualities: ['sharp', 'commanding', 'gravelly'] },
    Charon:       { ages: ['adult', 'mature'], archetypes: ['antagonist', 'narrator'], qualities: ['gravelly', 'calm', 'sharp'] },
    Umbriel:      { ages: ['adult'], archetypes: ['antagonist', 'supporting'], qualities: ['sharp', 'soft'] },
  }
};

function scoreVoice(voiceName, profile, character) {
  let score = 0;
  const age = character.age_range || 'adult';
  const archetype = character.archetype || 'supporting';
  const quality = character.vocal_quality || 'warm';

  if (profile.ages.includes(age)) score += 10;
  else if (profile.ages.includes('adult') && ['young_adult', 'mature'].includes(age)) score += 5;

  if (profile.archetypes.includes(archetype)) score += 8;
  else if (profile.archetypes[0] === 'supporting') score += 2;

  if (profile.qualities.includes(quality)) score += 5;

  return score;
}

function findBestVoice(character, gender, usedVoices) {
  const profiles = VOICE_PROFILES[gender] || VOICE_PROFILES.male;

  let bestVoice = null;
  let bestScore = -1;

  for (const [voiceName, profile] of Object.entries(profiles)) {
    if (usedVoices.has(voiceName)) continue;
    const score = scoreVoice(voiceName, profile, character);
    if (score > bestScore) {
      bestScore = score;
      bestVoice = voiceName;
    }
  }

  if (!bestVoice) {
    for (const [voiceName, profile] of Object.entries(profiles)) {
      const score = scoreVoice(voiceName, profile, character);
      if (score > bestScore) {
        bestScore = score;
        bestVoice = voiceName;
      }
    }
  }

  return bestVoice || (gender === 'female' ? 'Aoede' : 'Achird');
}

const userRole = detect.userRole?.toUpperCase() || '';
const userGender = detect.userGender?.toLowerCase() || '';  // Get user-specified gender
const usedFemaleVoices = new Set();
const usedMaleVoices = new Set();

// Merge structure characters with traits from emotions node
const characters = (structure.characters || []).map(c => {
  const name = (c.name || '').toUpperCase();
  const isUser = name === userRole || c.is_user_character === true;

  // Use userGender for user's character if provided, otherwise use AI-detected gender
  let gender = (c.gender || 'male').toLowerCase();
  if (isUser && userGender && userGender !== 'unknown') {
    gender = userGender;  // Override with user-specified gender
  }

  // Find traits from emotions response
  const traits = characterTraits.find(t => (t.name || '').toUpperCase() === name) || {};
  const ageRange = traits.age_range || 'adult';
  const archetype = traits.archetype || 'supporting';
  const vocalQuality = traits.vocal_quality || 'warm';

  // Build character object with traits for voice matching
  const charWithTraits = {
    name,
    gender,
    is_user_character: isUser,
    age_range: ageRange,
    archetype: archetype,
    vocal_quality: vocalQuality
  };

  let voiceName;
  if (name === 'NARRATOR') {
    voiceName = 'Rasalgethi';
  } else if (gender === 'female') {
    voiceName = findBestVoice(charWithTraits, 'female', usedFemaleVoices);
    usedFemaleVoices.add(voiceName);
  } else {
    voiceName = findBestVoice(charWithTraits, 'male', usedMaleVoices);
    usedMaleVoices.add(voiceName);
  }

  return {
    name,
    gender,
    is_user_character: isUser,
    age_range: ageRange,
    archetype: archetype,
    vocal_tone: vocalQuality,
    accent_hint: finalAccent,
    voice_id: `${locale}-Chirp3-HD-${voiceName}`,
    voice_name: voiceName
  };
});

// Ensure NARRATOR exists
if (!characters.find(c => c.name === 'NARRATOR')) {
  characters.push({
    name: 'NARRATOR',
    gender: 'male',
    is_user_character: false,
    age_range: 'mature',
    archetype: 'narrator',
    vocal_tone: 'calm',
    accent_hint: finalAccent,
    voice_id: `${locale}-Chirp3-HD-Rasalgethi`,
    voice_name: 'Rasalgethi'
  });
}

// Build scenes with lines
const scenes = (structure.scenes || []).map(s => ({
  ...s,
  lines: lines.filter(l => l.scene_number === s.scene_number)
}));

if (scenes.length === 0) {
  scenes.push({
    scene_number: 1,
    heading: 'Scene 1',
    int_ext: null,
    location: null,
    time_of_day: null,
    lines: lines
  });
}

return [{ json: {
  ...detect,
  accentHint: finalAccent,
  detectedAccent: structure.detected_accent || null,
  parsed: {
    title: structure.title || detect.title,
    scene_description: structure.scene_description || 'Script scene',
    format_type: 'screenplay',
    characters,
    scenes
  },
  totalLines: lines.length,
  dialogueLines: lines.filter(l => l.type === 'dialogue').length,
  actionLines: lines.filter(l => l.type === 'action').length
} }];

