const data = $('Get Script ID').first().json;
const scriptId = data.scriptId;
const userRole = (data.userRole || '').toUpperCase();
const parsed = data.parsed || {};
const allScenes = [];
const allLines = [];
let globalLineNum = 0;
const scenesData = parsed.scenes || [];

// Build scenes AND extract nested lines
scenesData.forEach((scene, sIdx) => {
  const sceneNum = scene.scene_number ?? sIdx + 1;

  allScenes.push({
    tempId: 'scene_' + sceneNum,
    script_id: scriptId,
    scene_number: sceneNum,
    name: [scene.int_ext, scene.location, scene.time_of_day].filter(Boolean).join(' ') || 'Scene ' + sceneNum,
    description: scene.description || null,
    int_ext: scene.int_ext || null,
    location: scene.location || null,
    time_of_day: scene.time_of_day || null,
    sort_order: sIdx
  });

  // Extract lines from NESTED scene.lines
  const sceneLines = scene.lines || [];
  sceneLines.forEach((line) => {
    globalLineNum++;
    const charName = (line.character || 'NARRATOR').toUpperCase();
    const content = line.content || '';

    allLines.push({
      tempSceneId: 'scene_' + sceneNum,
      script_id: scriptId,
      character_name: charName,
      content: content,
      parenthetical: line.parenthetical || null,
      emotion: line.emotion || 'neutral',
      is_user_line: charName === userRole,
      line_type: line.type || 'dialogue',
      line_number: globalLineNum,
      sort_order: line.sort_order || globalLineNum,
      word_count: content.split(/\s+/).filter(Boolean).length,
      practice_segments: line.practice_segments || null  // <-- ADD THIS
    });
  });
});

// Fallback if no scenes
if (allScenes.length === 0) {
  allScenes.push({
    tempId: 'scene_1',
    script_id: scriptId,
    scene_number: 1,
    name: 'Scene 1',
    description: parsed.scene_description || null,
    int_ext: null,
    location: null,
    time_of_day: null,
    sort_order: 0
  });
}

return [{ json: { ...data, scenesToCreate: allScenes, linesToCreate: allLines } }];

