const sceneResponse = $input.first().json;
const data = $('Build Data').first().json;
const sceneMap = {};

let scenesArray = [];
if (Array.isArray(sceneResponse)) {
  scenesArray = sceneResponse;
} else if (sceneResponse && sceneResponse.id) {
  scenesArray = [sceneResponse];
} else {
  scenesArray = $input.all().map(i => i.json).flat().filter(s => s && s.id);
}

// Map using scene_number (works for 0, 1, 2, etc.)
data.scenesToCreate.forEach((s) => {
  const dbScene = scenesArray.find(db => db.scene_number === s.scene_number);
  if (dbScene && dbScene.id) {
    sceneMap[s.tempId] = dbScene.id;
  }
});

const firstSceneId = Object.values(sceneMap)[0] || scenesArray[0]?.id || null;

const lines = data.linesToCreate.map(l => ({
  ...l,
  scene_id: sceneMap[l.tempSceneId] || firstSceneId
}));

const validLines = lines.filter(l => l.scene_id);

if (validLines.length === 0 && data.linesToCreate.length > 0) {
  throw new Error('Scene mapping failed. sceneMap: ' + JSON.stringify(sceneMap) + ', tempSceneIds: ' + JSON.stringify([...new Set(data.linesToCreate.map(l => l.tempSceneId))]));
}

return [{ json: { ...data, linesToCreate: validLines, sceneMap } }];

