  const isUserLine = l.is_user_line ? 'true' : 'false';
  const practiceSegments = l.practice_segments ? "'" + JSON.stringify(l.practice_segments).replace(/'/g, "''") + "'::jsonb" : 'NULL';
  return `('${l.script_id}'::uuid, '${l.scene_id}'::uuid, '${charName}', '${content}', ${parenthetical}, ${emotion}, ${isUserLine}, '${l.line_type}', ${l.line_number}, ${l.sort_order}, ${l.word_count}, ${practiceSegments})`;
}).join(', ');
return `INSERT INTO lines (script_id, scene_id, character_name, content, parenthetical, emotion, is_user_line, line_type, line_number, sort_order, word_count, practice_segments) VALUES ${values};`;
})() }}
